    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">D = 3 - √3 + 2 - y - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + 8 - 1 - <span class=\"frac\"><span class=\"num\">65</span><span class=\"den\">6</span></span> + 2√3</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">D = -y + (3 + 2 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + 8 - 1 - <span class=\"frac\"><span class=\"num\">65</span><span class=\"den\">6</span></span>) + (-√3 + 2√3)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">D = -y - 1 + √3</span>"}],
