    correction: [{"quoi":"نترجم المعطى","math":"متساويان معناه <span dir=\"ltr\" class=\"expr\">D = -3 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-y + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3 = -3 - π</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">-y = -3 - π - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-3 - π - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3) = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √3 - π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - √3 + π</span>"}],
