    correction: [{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r ؛</span> و إذا كان r سالبا فلا حلّ"},{"quoi":"نكتب ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">D + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> = -y + 3 - √3</span>"},{"quoi":"الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\">-y + 3 - √3 = 4</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">y = -1 - √3</span>"},{"quoi":"الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\">-y + 3 - √3 = -4</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">y = 7 - √3</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن اثنان"}],
