    enonce: "بيّن أنّ <span dir=\"ltr\" class=\"expr\">F = a - b - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + π</span> حيث <span dir=\"ltr\" class=\"expr\">F = [4 + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span>] - [-2 - (-a - π + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span>)] + 3 + 2a - b - 15 + 2π</span>",
    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = 4 + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + 2 - a - π + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + 3 + 2a - b - 15 + 2π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (-a + 2a) - b + (4 + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + 2 + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + 3 - 15) + (-π + 2π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = a - b - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + π</span>"}],
