    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + [-√3 - (a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span>)] + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">27</span><span class=\"den\">10</span></span> = -a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">-a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3 = -1 - √3</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">-a = -1 - √3 - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-1 - √3 - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - √3) = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"}],
