    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">[b - 1 - b] + [-b - (-2 + b + b)] + √2 + 4b - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - 2√2 = b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2 = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - √2</span>"},{"quoi":"نعزل b","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - √2 - (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - √2 - (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - √2) = 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = 2</span>"}],
