    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + √2 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + 1 - √2 + b - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - 2 + √2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> + a + b + <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">12</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = a + (b + b) + (3 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + 1 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - 2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">12</span></span>) + (√2 - √2 + √2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = a + 2b - 1 + √2</span>"}],
