    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - 4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 9 - a + 3 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + b + 3a - 6 - π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = (-a + 3a) + b + (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - 4 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 9 + 3 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - 6) - π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 2a + b - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - π</span>"}],
