    correction: [{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: M + N = 0</span>"},{"quoi":"نجمع الشكلين المختصرين","math":"<span dir=\"ltr\" class=\"expr\">M + N = 3a + 3b - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + √2 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">3a + 3b - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + √2 - π = 0</span>"},{"quoi":"نعزل حدود الحرفين","math":"<span dir=\"ltr\" class=\"expr\">3a + 3b = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - √2 + π</span>"},{"quoi":"نقسم على المعامل","math":"<span dir=\"ltr\" class=\"expr\">a + b = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> √2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a + b = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> √2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> π</span>"}],
