    enonce: "بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> + √3</span> حيث <span dir=\"ltr\" class=\"expr\">M = a + [a + (-√3 + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span>)] + (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - 1) - (-a - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>) - 4a - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">4</span></span> + 2√3</span>",
